// Predicate evaluation, three-valued.
//
// Generated by `ess verify conform synthesize --target go`. Do not edit.
//
// # Why three values
//
// True, False and Unknown. The third is the point: `total.amount >= 0` is *false* when a row breaks
// the invariant and *unknown* when the row does not publish `total.amount` at all, and those need
// different responses — fix the implementation, or fix the specification or the view. A runner that
// collapsed them would report a missing field as a broken invariant.
package essconform

import (
	"encoding/json"
	"fmt"
	"math"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// truth is a three-valued result.
type truth int

const (
	truthTrue truth = iota
	truthFalse
	truthUnknown
)

func (t truth) and(other truth) truth {
	if t == truthFalse || other == truthFalse {
		return truthFalse
	}
	if t == truthUnknown || other == truthUnknown {
		return truthUnknown
	}
	return truthTrue
}

func (t truth) or(other truth) truth {
	if t == truthTrue || other == truthTrue {
		return truthTrue
	}
	if t == truthUnknown || other == truthUnknown {
		return truthUnknown
	}
	return truthFalse
}

func (t truth) not() truth {
	switch t {
	case truthTrue:
		return truthFalse
	case truthFalse:
		return truthTrue
	default:
		return truthUnknown
	}
}

// factSource is a flattened row: a scalar per dotted path.
//
// A mapping or a sequence also holds `aggregatePresent{}` at its own path, even when it is empty:
// what `defined()` over an Optional struct, list or map reads (beyond10x/ess#176). No value read
// sees it — `readLeaf` treats it as unbound.
//
// A collection publishes its size as `<path>.count` and its elements as `<path>.0.…`, which is what
// a quantifier counts through. Same convention the specification half uses, so a predicate written
// against the model evaluates here without translation.
type factSource map[string]Node

// aggregatePresent marks a path holding a mapping or a sequence, which binds no scalar of its own.
type aggregatePresent struct{}

// facts flattens one row into the paths a predicate reads.
func facts(row Row) factSource {
	flattened := factSource{}
	for field, value := range row {
		bindFact(flattened, field, value)
	}
	return flattened
}

func bindFact(into factSource, path string, value Node) {
	switch value := value.(type) {
	case map[string]any:
		into[path] = aggregatePresent{}
		for key, nested := range value {
			bindFact(into, path+"."+key, nested)
		}
	case []any:
		// The size as well as the elements: a quantifier has no collection value to ask for a
		// length, so the length is a fact like any other.
		into[path] = aggregatePresent{}
		into[path+".count"] = float64(len(value))
		for index, nested := range value {
			bindFact(into, fmt.Sprintf("%s.%d", path, index), nested)
		}
	default:
		into[path] = value
	}
}

// ---- the predicate ----------------------------------------------------------------------------

// predicate is a condition over facts.
type predicate struct {
	kind     string
	children []predicate
	// leaf
	left  operand
	op    string
	right operand
	// instant is a tagged comparison (`as: timestamp`, suite/40): the operands compare as the
	// RFC 3339 instants they name, never by their spelling.
	instant bool
	path    string
	// any_of / none_of
	values []Node
	// quantifier
	over string
	bind string
	body *predicate
}

// operand is one side of a comparison: a fact to look up, or a constant.
type operand struct {
	path    string
	literal Node
	isFact  bool
}

func (p predicate) String() string {
	switch p.kind {
	case "always":
		return "always"
	case "never":
		return "never"
	case "all", "any":
		parts := make([]string, 0, len(p.children))
		for _, child := range p.children {
			parts = append(parts, child.String())
		}
		joiner := " and "
		if p.kind == "any" {
			joiner = " or "
		}
		return "(" + strings.Join(parts, joiner) + ")"
	case "not":
		return "not (" + p.body.String() + ")"
	case "compare":
		if p.instant {
			return fmt.Sprintf("%s %s %s as timestamp", p.left, p.op, p.right)
		}
		return fmt.Sprintf("%s %s %s", p.left, p.op, p.right)
	case "truthy":
		return p.path
	case "defined":
		return "defined(" + p.path + ")"
	case "any_of", "none_of":
		parts := make([]string, 0, len(p.values))
		for _, value := range p.values {
			parts = append(parts, render(value))
		}
		word := " in ["
		if p.kind == "none_of" {
			word = " not in ["
		}
		return p.path + word + strings.Join(parts, ", ") + "]"
	case "starts_with", "ends_with", "contains":
		return fmt.Sprintf("%s %s %q", p.path, p.kind, p.right.literal)
	case "equals_ignore_case":
		if len(p.values) == 1 {
			return fmt.Sprintf("%s %s %q", p.path, p.kind, p.values[0])
		}
		fallthrough
	case "in_ignore_case":
		parts := make([]string, 0, len(p.values))
		for _, value := range p.values {
			parts = append(parts, fmt.Sprintf("%q", value))
		}
		return p.path + " " + p.kind + " [" + strings.Join(parts, ", ") + "]"
	case "forall", "exists":
		return fmt.Sprintf("%s %s in %s: (%s)", p.kind, p.bind, p.over, p.body)
	default:
		return p.kind
	}
}

func (o operand) String() string {
	if o.isFact {
		return o.path
	}
	return render(o.literal)
}

// parsePredicate reads a predicate out of the suite.
func parsePredicate(raw json.RawMessage) (predicate, error) {
	if len(raw) == 0 {
		return predicate{}, fmt.Errorf("no predicate is written")
	}
	var node any
	decoder := json.NewDecoder(strings.NewReader(string(raw)))
	if err := decoder.Decode(&node); err != nil {
		return predicate{}, err
	}
	return fromNode(node)
}

func fromNode(node any) (predicate, error) {
	return fromNodeIn(node, nil)
}

// fromNodeIn reads a predicate inside quantifier bodies whose binders are `binders`, innermost last
// (beyond10x/ess#289), as Rust's `from_node_nested` does.
func fromNodeIn(node any, binders []string) (predicate, error) {
	switch node := node.(type) {
	case bool:
		if node {
			return predicate{kind: "always"}, nil
		}
		return predicate{kind: "never"}, nil
	case string:
		return parseLeafIn(node, binders)
	case []any:
		children, err := fromNodes(node, binders)
		if err != nil {
			return predicate{}, err
		}
		return predicate{kind: "all", children: children}, nil
	case map[string]any:
		// Sorted, so a mapping with more than one entry parses the same way twice. Go randomises
		// map iteration, and a predicate that reordered between runs would make a failure report
		// unreadable across two of them.
		keys := make([]string, 0, len(node))
		for key := range node {
			keys = append(keys, key)
		}
		sort.Strings(keys)

		children := make([]predicate, 0, len(keys))
		for _, key := range keys {
			child, err := fromEntry(key, node[key], binders)
			if err != nil {
				return predicate{}, err
			}
			children = append(children, child)
		}
		if len(children) == 1 {
			return children[0], nil
		}
		return predicate{kind: "all", children: children}, nil
	default:
		return predicate{}, fmt.Errorf("a predicate is an expression, a list or a mapping, not %T", node)
	}
}

func fromNodes(nodes []any, binders []string) ([]predicate, error) {
	parsed := make([]predicate, 0, len(nodes))
	for _, node := range nodes {
		child, err := fromNodeIn(node, binders)
		if err != nil {
			return nil, err
		}
		parsed = append(parsed, child)
	}
	return parsed, nil
}

func fromEntry(key string, value any, binders []string) (predicate, error) {
	switch key {
	case "all", "and", "all_of", "any", "or":
		items, ok := value.([]any)
		if !ok {
			items = []any{value}
		}
		children, err := fromNodes(items, binders)
		if err != nil {
			return predicate{}, err
		}
		kind := "all"
		if key == "any" || key == "or" {
			kind = "any"
		}
		return predicate{kind: kind, children: children}, nil
	case "not":
		inner, err := fromNodeIn(value, binders)
		if err != nil {
			return predicate{}, err
		}
		return predicate{kind: "not", body: &inner}, nil
	case "forall", "exists":
		return parseQuantifier(key, value, binders)
	case "compare":
		if fields, ok := value.(map[string]any); ok {
			if _, tagged := fields["left"]; tagged {
				return parseTaggedCompare(fields, binders)
			}
		}
		return parseConstraint(key, value, binders)
	default:
		return parseConstraint(key, value, binders)
	}
}

// parseTaggedCompare reads `{compare: {left, op, right, as: timestamp}}`, a comparison tagged to
// compare instants (suite/40, docs/design/expression-family-source22.md decision 2), as Rust's
// `Predicate::tagged_compare` does: exactly those four keys. A mapping under `compare` without
// `left` is a constraint on a fact named `compare`, as it always was.
func parseTaggedCompare(fields map[string]any, binders []string) (predicate, error) {
	refuse := func(reason string) (predicate, error) {
		return predicate{}, fmt.Errorf("compare: %s", reason)
	}
	if len(fields) != 4 {
		return refuse("a tagged comparison takes exactly `left`, `op`, `right` and `as`")
	}
	left, ok := fields["left"].(string)
	if !ok || !factPath.MatchString(left) {
		return refuse("`left` names a fact path")
	}
	spelled, _ := fields["op"].(string)
	op, ok := compareSpellings[spelled]
	if !ok {
		return refuse("`op` is one of eq, ne, lt, lte, gt, gte")
	}
	if kind, _ := fields["as"].(string); kind != "timestamp" {
		return refuse("`as` names the one kind a comparison is tagged with, `timestamp`")
	}
	var right operand
	switch value := fields["right"].(type) {
	case string:
		right = parseOperandIn(value, binders)
	case map[string]any:
		fact, err := parseFactOperand("compare", "right", value)
		if err != nil {
			return predicate{}, err
		}
		right = fact
	case bool, json.Number, float64:
		right = operand{literal: value}
	default:
		return refuse("`right` is a scalar or `{fact: <path>}`")
	}
	return predicate{kind: "compare", left: operand{path: left, isFact: true}, op: op, right: right, instant: true}, nil
}

func parseQuantifier(kind string, value any, binders []string) (predicate, error) {
	mapping, ok := value.(map[string]any)
	if !ok {
		return predicate{}, fmt.Errorf("a quantifier is a mapping with `in`, `as` and `that`")
	}
	over, _ := mapping["in"].(string)
	bind, _ := mapping["as"].(string)
	if over == "" || bind == "" {
		return predicate{}, fmt.Errorf("a quantifier needs both `in` and `as`")
	}
	body, err := fromNodeIn(mapping["that"], append(append([]string(nil), binders...), bind))
	if err != nil {
		return predicate{}, err
	}
	return predicate{kind: kind, over: over, bind: bind, body: &body}, nil
}

func parseConstraint(path string, value any, binders []string) (predicate, error) {
	mapping, ok := value.(map[string]any)
	if !ok {
		return predicate{
			kind:  "compare",
			left:  operand{path: path, isFact: true},
			op:    "==",
			right: operand{literal: value},
		}, nil
	}
	// Every operator of one mapping is conjoined, as Rust's `from_constraint` does, in sorted key
	// order so that one mapping parses the same way twice (Go randomises map iteration).
	keys := make([]string, 0, len(mapping))
	for key := range mapping {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	children := make([]predicate, 0, len(keys))
	for _, key := range keys {
		child, err := parseOperator(path, key, mapping[key], binders)
		if err != nil {
			return predicate{}, err
		}
		children = append(children, child)
	}
	switch len(children) {
	case 0:
		return predicate{kind: "always"}, nil
	case 1:
		return children[0], nil
	default:
		return predicate{kind: "all", children: children}, nil
	}
}

var compareSpellings = map[string]string{
	"eq": "==", "equals": "==", "==": "==",
	"ne": "!=", "not_equals": "!=", "!=": "!=",
	"lt": "<", "<": "<",
	"le": "<=", "lte": "<=", "<=": "<=",
	"gt": ">", ">": ">",
	"ge": ">=", "gte": ">=", ">=": ">=",
}

// parseOperator reads one operator of a constraint mapping, as Rust's `from_operator` does.
func parseOperator(path, key string, raw any, binders []string) (predicate, error) {
	if op, ok := compareSpellings[key]; ok {
		right := operand{literal: raw}
		switch value := raw.(type) {
		case string:
			right = parseOperandIn(value, binders)
		case map[string]any:
			fact, err := parseFactOperand(path, key, value)
			if err != nil {
				return predicate{}, err
			}
			right = fact
		}
		return predicate{kind: "compare", left: operand{path: path, isFact: true}, op: op, right: right}, nil
	}
	switch key {
	case "any_of", "in", "one_of", "none_of", "not_in":
		kind := "any_of"
		if key == "none_of" || key == "not_in" {
			kind = "none_of"
		}
		// Rust reads a scalar as a one-element list and null as the empty one.
		var items []any
		switch listed := raw.(type) {
		case nil:
		case []any:
			items = listed
		default:
			items = []any{listed}
		}
		return predicate{kind: kind, path: path, values: items}, nil
	case "starts_with", "ends_with", "contains":
		// Verbatim, never through parseOperand: `"+44"` is text and `"a.b"` is no fact path.
		text, ok := raw.(string)
		if !ok {
			return predicate{}, fmt.Errorf("`%s: {%s: …}` takes a string", path, key)
		}
		return predicate{kind: key, path: path, right: operand{literal: text}}, nil
	case "equals_ignore_case":
		// Verbatim, as for a string operator (beyond10x/ess#140).
		text, ok := raw.(string)
		if !ok {
			return predicate{}, fmt.Errorf("`%s: {%s: …}` takes a string", path, key)
		}
		return predicate{kind: key, path: path, values: []Node{text}}, nil
	case "in_ignore_case":
		items, ok := raw.([]any)
		if !ok {
			return predicate{}, fmt.Errorf("`%s: {%s: …}` takes a list of strings", path, key)
		}
		values := make([]Node, 0, len(items))
		for _, item := range items {
			text, ok := item.(string)
			if !ok {
				return predicate{}, fmt.Errorf("`%s: {%s: …}` takes a list of strings", path, key)
			}
			values = append(values, text)
		}
		return predicate{kind: key, path: path, values: values}, nil
	case "exists", "defined":
		expected, ok := raw.(bool)
		if !ok {
			return predicate{}, fmt.Errorf("`%s: {%s: …}` takes a boolean", path, key)
		}
		defined := predicate{kind: "defined", path: path}
		if expected {
			return defined, nil
		}
		return predicate{kind: "not", body: &defined}, nil
	case "truthy":
		return predicate{kind: "truthy", path: path}, nil
	}
	return predicate{}, fmt.Errorf("`%s` carries the operator %q, which this runner does not know", path, key)
}

// parseFactOperand reads the explicit fact operand `{fact: <path>}`, the canonical spelling of a
// one-segment fact on the right of a comparison (suite/40, docs/design/expression-family-source22.md
// A1), as Rust's `Operand::fact_mapping` does: exactly one key, naming a fact path. Anything else
// is refused rather than compared as the mapping it is. Which suite majors may carry it is the
// runtime's admission to decide; this reader only reads it.
func parseFactOperand(path, key string, value map[string]any) (operand, error) {
	fact, ok := value["fact"].(string)
	if len(value) != 1 || !ok || !factPath.MatchString(fact) {
		return operand{}, fmt.Errorf("`%s: {%s: …}`: a comparison operand must be a scalar, or `{fact: <path>}` naming a fact", path, key)
	}
	return operand{path: fact, isFact: true}, nil
}

// parseLeaf reads compact expressions. Unrepresentable literal data uses structured comparisons.
func parseLeaf(expression string) (predicate, error) {
	return parseLeafIn(expression, nil)
}

// parseLeafIn reads a compact expression inside quantifier bodies whose binders are `binders`.
func parseLeafIn(expression string, binders []string) (predicate, error) {
	if err := admitPredicateExpression(expression, 0); err != nil {
		return predicate{}, err
	}
	trimmed := strings.TrimSpace(expression)
	if rest, ok := strings.CutPrefix(trimmed, "not "); ok {
		inner, err := parseLeafIn(rest, binders)
		if err != nil {
			return predicate{}, err
		}
		return predicate{kind: "not", body: &inner}, nil
	}
	if trimmed == "always" {
		return predicate{kind: "always"}, nil
	}
	if trimmed == "never" {
		return predicate{kind: "never"}, nil
	}
	if rest, ok := strings.CutPrefix(trimmed, "defined("); ok {
		path, ok := strings.CutSuffix(rest, ")")
		if !ok {
			return predicate{}, fmt.Errorf("`%s` opens `defined(` and does not close it", trimmed)
		}
		return predicate{kind: "defined", path: strings.TrimSpace(path)}, nil
	}
	if left, op, right, ok := splitPredicateComparison(trimmed); ok {
		return predicate{
			kind: "compare",
			// The left-hand side of a comparison is always a fact path, never a literal —
			// which is what `Predicate::parse_expression` does on the Rust side, and the two
			// have to agree or the same specification says different things to two runners.
			// Read as a literal instead, `reschedule_count >= 0` compares the *word* to zero
			// and `state == Bridged` compares two words, which is false and silently vacuous
			// under the `not` an implication is written with.
			left:  operand{path: strings.TrimSpace(left), isFact: true},
			op:    op,
			right: parseOperandIn(right, binders),
		}, nil
	}
	if strings.ContainsAny(trimmed, " ()[]") {
		return predicate{}, fmt.Errorf("`%s` is an expression this generated runner does not implement", trimmed)
	}
	return predicate{kind: "truthy", path: trimmed}, nil
}

// parseOperand reads the right-hand side of a comparison.
//
// A bare word containing a dot is a fact path and anything else is a literal, which is the model's
// own rule; a literal containing dots is quoted.
func parseOperand(raw string) operand {
	return parseOperandIn(raw, nil)
}

// parseOperandIn is parseOperand inside quantifier bodies: an unquoted word that is exactly the
// name of a binder in scope reads that binder (beyond10x/ess#289), as Rust's `Operand::parse_in`
// does. Quoted, it is the text.
func parseOperandIn(raw string, binders []string) operand {
	trimmed := strings.TrimSpace(raw)
	quoted := strings.HasPrefix(trimmed, "\"") || strings.HasPrefix(trimmed, "'")
	if !quoted && factPath.MatchString(trimmed) {
		for _, binder := range binders {
			if binder == trimmed {
				return operand{path: trimmed, isFact: true}
			}
		}
	}
	if !quoted && strings.Contains(trimmed, ".") {
		if _, numeric := parseDecimalLiteral(trimmed); !numeric && factPath.MatchString(trimmed) {
			return operand{path: trimmed, isFact: true}
		}
	}
	return operand{literal: parseLiteral(trimmed)}
}

func parseLiteral(raw string) Node {
	if len(raw) >= 2 {
		for _, quote := range []string{"\"", "'"} {
			if strings.HasPrefix(raw, quote) && strings.HasSuffix(raw, quote) {
				return raw[1 : len(raw)-1]
			}
		}
	}
	switch raw {
	case "true":
		return true
	case "false":
		return false
	}
	if number, ok := parseDecimalLiteral(raw); ok {
		return number
	}
	return raw
}

// Rust Number::parse_decimal admits finite decimal f64 literals. strconv also accepts NaN,
// infinities, hexadecimal floats and underscores; those spellings remain text in predicates.
func parseDecimalLiteral(raw string) (float64, bool) {
	if !meaningDecimal.MatchString(raw) {
		return 0, false
	}
	number, err := strconv.ParseFloat(raw, 64)
	return number, err == nil && !math.IsNaN(number) && !math.IsInf(number, 0)
}

// ---- admission --------------------------------------------------------------------------------

// Compact string leaves are the only envelope shape this file reads; the runtime admits the
// structured shapes, which need its reader. Both spend the same Rust depth budget, and the
// definitions below stay here so this file depends on nothing the runtime declares.
func admitPredicateExpression(expression string, depth int) error {
	if depth > 32 {
		return fmt.Errorf("predicate exceeds maximum depth 32")
	}
	if rest, ok := strings.CutPrefix(strings.TrimSpace(expression), "not "); ok {
		return admitPredicateExpression(rest, depth+1)
	}
	return admitPredicateLeaf(expression)
}

func admitPredicatePath(path string) error {
	if !factPath.MatchString(path) {
		return fmt.Errorf("invalid predicate fact path %q", path)
	}
	return nil
}

func admitPredicateLeaf(expression string) error {
	trimmed := strings.TrimSpace(expression)
	switch trimmed {
	case "always", "true", "never", "false":
		return nil
	}
	for _, function := range []string{"defined", "exists", "missing"} {
		if rest, ok := strings.CutPrefix(trimmed, function); ok {
			if rest, ok := strings.CutPrefix(strings.TrimSpace(rest), "("); ok {
				if path, ok := strings.CutSuffix(strings.TrimSpace(rest), ")"); ok {
					return admitPredicatePath(strings.TrimSpace(path))
				}
			}
		}
	}
	if left, _, right, ok := splitPredicateComparison(trimmed); ok {
		if err := admitPredicatePath(strings.TrimSpace(left)); err != nil {
			return err
		}
		if strings.TrimSpace(right) == "" {
			return fmt.Errorf("predicate comparison requires a right operand")
		}
		return admitQuotedOperand(right)
	}
	return admitPredicatePath(trimmed)
}

// Quoting delimits one compact operand. Escape bytes retain their historical literal value;
// they only prevent an escaped quote from ending the operand. Structured scalar data is separate.
func admitQuotedOperand(raw string) error {
	trimmed := strings.TrimSpace(raw)
	if trimmed == "" || (trimmed[0] != '"' && trimmed[0] != '\'') {
		return nil
	}
	quote, escaped := trimmed[0], false
	for index := 1; index < len(trimmed); index++ {
		ch := trimmed[index]
		if escaped {
			escaped = false
		} else if ch == '\\' {
			escaped = true
		} else if ch == quote {
			if strings.TrimSpace(trimmed[index+1:]) != "" {
				return fmt.Errorf("tokens after a quoted operand are unsupported; use structured any/all/not")
			}
			return nil
		}
	}
	return fmt.Errorf("quoted operand is not closed; close the quote and use structured any/all/not to combine predicates")
}

// Rust split_comparison chooses the first operator outside quotes, examining two-byte
// operators before one-byte operators at that position. Admission and evaluation share the split.
func splitPredicateComparison(trimmed string) (string, string, string, bool) {
	var quote byte
	for index := 0; index < len(trimmed); index++ {
		ch := trimmed[index]
		if quote != 0 {
			if ch == quote {
				quote = 0
			}
			continue
		}
		if ch == '\'' || ch == '"' {
			quote = ch
			continue
		}
		width := 0
		if index+1 < len(trimmed) {
			switch trimmed[index : index+2] {
			case "==", "!=", "<=", ">=":
				width = 2
			}
		}
		if width == 0 && (ch == '<' || ch == '>') {
			width = 1
		}
		if width != 0 {
			return trimmed[:index], trimmed[index : index+width], trimmed[index+width:], true
		}
	}
	return "", "", "", false
}

var meaningDecimal = regexp.MustCompile(`^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)([eE][+-]?[0-9]+)?$`)

var factPath = regexp.MustCompile(`^_*[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z0-9_-]+)*$`)

// ---- evaluation -------------------------------------------------------------------------------

func (p predicate) evaluate(source factSource) truth {
	switch p.kind {
	case "always":
		return truthTrue
	case "never":
		return truthFalse
	case "all":
		result := truthTrue
		for _, child := range p.children {
			result = result.and(child.evaluate(source))
		}
		return result
	case "any":
		result := truthFalse
		for _, child := range p.children {
			result = result.or(child.evaluate(source))
		}
		return result
	case "not":
		return p.body.evaluate(source).not()
	case "compare":
		return p.compare(source)
	case "truthy":
		value, ok := readLeaf(source, p.path)
		if !ok {
			return truthUnknown
		}
		return truthOf(isTruthy(value))
	case "defined":
		return truthOf(present(source, p.path))
	case "any_of", "none_of":
		value, ok := readLeaf(source, p.path)
		if !ok {
			return truthUnknown
		}
		found := false
		for _, candidate := range p.values {
			if equal(value, candidate) {
				found = true
				break
			}
		}
		return truthOf(found == (p.kind == "any_of"))
	case "starts_with", "ends_with", "contains":
		return p.textMatch(source)
	case "equals_ignore_case", "in_ignore_case":
		return p.foldMatch(source)
	case "forall", "exists":
		return p.quantify(source)
	default:
		return truthUnknown
	}
}

func (p predicate) compare(source factSource) truth {
	left, leftOk := p.left.resolve(source)
	right, rightOk := p.right.resolve(source)
	if !leftOk || !rightOk {
		return truthUnknown
	}
	if p.instant {
		// Decision 2: the instants the two operands name, under every operator. A text that names
		// no instant is Unknown, never ordered by its spelling.
		leftText, leftIsText := left.(string)
		rightText, rightIsText := right.(string)
		leftInstant, leftOk := parseInstant(leftText)
		rightInstant, rightOk := parseInstant(rightText)
		if !leftIsText || !rightIsText || !leftOk || !rightOk {
			return truthUnknown
		}
		return truthOf(acceptsOrder(p.op, leftInstant.compare(rightInstant)))
	}
	if p.op == "==" || p.op == "!=" {
		return truthOf(equal(left, right) == (p.op == "=="))
	}
	order, ok := compare(left, right)
	if !ok {
		return truthUnknown
	}
	switch p.op {
	case "<":
		return truthOf(order < 0)
	case "<=":
		return truthOf(order <= 0)
	case ">":
		return truthOf(order > 0)
	case ">=":
		return truthOf(order >= 0)
	default:
		return truthUnknown
	}
}

// acceptsOrder applies a comparison operator to an ordering, as Rust's `CompareOp::accepts` does.
func acceptsOrder(op string, order int) bool {
	switch op {
	case "==":
		return order == 0
	case "!=":
		return order != 0
	case "<":
		return order < 0
	case "<=":
		return order <= 0
	case ">":
		return order > 0
	default:
		return order >= 0
	}
}

// instant is one RFC 3339 `date-time` as a point on the UTC line: whole seconds since the epoch
// and nanoseconds, as Rust's `Rfc3339Instant` holds it.
type instant struct {
	seconds int64
	nanos   int64
}

func (a instant) compare(b instant) int {
	switch {
	case a.seconds < b.seconds:
		return -1
	case a.seconds > b.seconds:
		return 1
	case a.nanos < b.nanos:
		return -1
	case a.nanos > b.nanos:
		return 1
	}
	return 0
}

// parseInstant is Rust's `Rfc3339Instant::parse_rfc3339` (decision 14): the `date-time`
// production and nothing wider — `T` or `t`, seconds 00–59 (no leap second), up to nine fraction
// digits, and `Z`, `z` or a `±HH:MM` offset; years 0000–9999 with real month lengths. The vectors
// it answers are `crates/specify/ess-primitives/tests/vectors/rfc3339-instants.json`.
func parseInstant(text string) (instant, bool) {
	digits := func(from, to int) (int64, bool) {
		if from >= to || to > len(text) {
			return 0, false
		}
		var total int64
		for index := from; index < to; index++ {
			c := text[index]
			if c < '0' || c > '9' {
				return 0, false
			}
			total = total*10 + int64(c-'0')
		}
		return total, true
	}
	at := func(index int, expected string) bool {
		return index < len(text) && strings.IndexByte(expected, text[index]) >= 0
	}
	if !(at(4, "-") && at(7, "-") && at(10, "Tt") && at(13, ":") && at(16, ":")) {
		return instant{}, false
	}
	year, ok1 := digits(0, 4)
	month, ok2 := digits(5, 7)
	day, ok3 := digits(8, 10)
	hour, ok4 := digits(11, 13)
	minute, ok5 := digits(14, 16)
	second, ok6 := digits(17, 19)
	if !(ok1 && ok2 && ok3 && ok4 && ok5 && ok6) || month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month) || hour > 23 || minute > 59 || second > 59 {
		return instant{}, false
	}
	position := 19
	var nanos int64
	if at(position, ".") {
		end := position + 1
		for end < len(text) && text[end] >= '0' && text[end] <= '9' {
			end++
		}
		width := end - position - 1
		if width == 0 || width > 9 {
			return instant{}, false
		}
		fraction, _ := digits(position+1, end)
		for scale := width; scale < 9; scale++ {
			fraction *= 10
		}
		nanos = fraction
		position = end
	}
	var offset int64
	rest := text[position:]
	switch {
	case rest == "Z" || rest == "z":
	case len(rest) == 6 && (rest[0] == '+' || rest[0] == '-') && rest[3] == ':':
		hours, okH := digits(position+1, position+3)
		minutes, okM := digits(position+4, position+6)
		if !okH || !okM || hours > 23 || minutes > 59 {
			return instant{}, false
		}
		offset = hours*3600 + minutes*60
		if rest[0] == '-' {
			offset = -offset
		}
	default:
		return instant{}, false
	}
	return instant{seconds: daysFromCivil(year, month, day)*86400 + hour*3600 + minute*60 + second - offset, nanos: nanos}, true
}

func daysInMonth(year, month int64) int64 {
	switch month {
	case 2:
		if (year%4 == 0 && year%100 != 0) || year%400 == 0 {
			return 29
		}
		return 28
	case 4, 6, 9, 11:
		return 30
	default:
		return 31
	}
}

// daysFromCivil counts days from 1970-01-01 to a proleptic Gregorian date.
func daysFromCivil(year, month, day int64) int64 {
	if month <= 2 {
		year--
	}
	era := year
	if era < 0 {
		era -= 399
	}
	era /= 400
	yoe := year - era*400
	shifted := month + 9
	if month > 2 {
		shifted = month - 3
	}
	doy := (153*shifted+2)/5 + day - 1
	doe := yoe*365 + yoe/4 - yoe/100 + doy
	return era*146097 + doe - 719468
}

// textMatch is a string operator (beyond10x/ess#95): byte-wise and case-sensitive, as
// `strings` answers over the UTF-8 bytes `encoding/json` decoded. Unbound, or bound to the null
// the flattener binds, is Unknown; a value that is not text is False.
func (p predicate) textMatch(source factSource) truth {
	value, ok := readLeaf(source, p.path)
	if !ok || value == nil {
		return truthUnknown
	}
	text, isText := value.(string)
	literal, literalText := p.right.literal.(string)
	if !isText || !literalText {
		return truthFalse
	}
	switch p.kind {
	case "starts_with":
		return truthOf(strings.HasPrefix(text, literal))
	case "ends_with":
		return truthOf(strings.HasSuffix(text, literal))
	default:
		return truthOf(strings.Contains(text, literal))
	}
}

// foldMatch is a case-insensitive operator (beyond10x/ess#140): the text equals one of the literals
// under ASCII case folding. Not `strings.EqualFold`, which folds Unicode — it equates the Kelvin sign
// with `k` — where every lane folds `A`–`Z` alone. Unbound, or bound to the null the flattener
// binds, is Unknown; a value that is not text is False.
func (p predicate) foldMatch(source factSource) truth {
	value, ok := readLeaf(source, p.path)
	if !ok || value == nil {
		return truthUnknown
	}
	text, isText := value.(string)
	if !isText {
		return truthFalse
	}
	for _, candidate := range p.values {
		if literal, ok := candidate.(string); ok && asciiEqualFold(text, literal) {
			return truthTrue
		}
	}
	return truthFalse
}

// asciiEqualFold compares two texts byte for byte after mapping `A`–`Z` to `a`–`z`.
func asciiEqualFold(left, right string) bool {
	if len(left) != len(right) {
		return false
	}
	for index := 0; index < len(left); index++ {
		a, b := left[index], right[index]
		if 'A' <= a && a <= 'Z' {
			a += 'a' - 'A'
		}
		if 'A' <= b && b <= 'Z' {
			b += 'a' - 'A'
		}
		if a != b {
			return false
		}
	}
	return true
}

// quantify walks the collection, rebinding the body's reads onto each element.
//
// An unobserved collection is Unknown, never the vacuous truth an empty one gives: *nobody looked*
// and *there was nothing to look at* are the two situations three-valued logic exists to separate.
func (p predicate) quantify(source factSource) truth {
	size, ok := source[p.over+".count"]
	if !ok {
		return truthUnknown
	}
	count, ok := asNumber(size)
	if !ok || count < 0 || count != float64(int(count)) {
		return truthUnknown
	}

	universal := p.kind == "forall"
	result := truthFalse
	if universal {
		result = truthTrue
	}
	for index := 0; index < int(count); index++ {
		element := rebind(source, p.bind, fmt.Sprintf("%s.%d", p.over, index))
		got := p.body.evaluate(element)
		if universal {
			result = result.and(got)
			if result == truthFalse {
				break
			}
		} else {
			result = result.or(got)
			if result == truthTrue {
				break
			}
		}
	}
	return result
}

// rebind is the source seen from inside one element: reads of `<bind>.rest` become reads of
// `<prefix>.rest`, and every other path passes through.
func rebind(source factSource, bind, prefix string) factSource {
	bound := factSource{}
	for path, value := range source {
		bound[path] = value
	}
	for path, value := range source {
		if path == prefix {
			bound[bind] = value
			continue
		}
		if rest, ok := strings.CutPrefix(path, prefix+"."); ok {
			bound[bind+"."+rest] = value
		}
	}
	return bound
}

func (o operand) resolve(source factSource) (Node, bool) {
	if !o.isFact {
		return o.literal, true
	}
	return readLeaf(source, o.path)
}

// readLeaf is one leaf read, the rule every evaluator lane shares (beyond10x/ess#104): a bound fact
// wins; otherwise, when the last segment is `count` and the parent is bound to text, the value is
// the text's rune count, which is its number of Unicode scalar values for the valid UTF-8
// `encoding/json` decodes. A quantifier's cardinality is read raw, so a quantifier over a text is
// Unknown.
func readLeaf(source factSource, path string) (Node, bool) {
	if value, ok := source[path]; ok {
		if _, aggregate := value.(aggregatePresent); aggregate {
			return nil, false
		}
		return value, true
	}
	parent, last, found := cutLast(path)
	if !found || last != "count" {
		return nil, false
	}
	if text, isText := source[parent].(string); isText {
		return float64(utf8.RuneCountInString(text)), true
	}
	return nil, false
}

// present is what `defined()` reads, the rule every evaluator lane shares (beyond10x/ess#176): a
// bound scalar, a text's derived length, or a mapping or sequence — present even when empty — is
// present; `null` and a path nothing binds are absent.
func present(source factSource, path string) bool {
	if value, ok := source[path]; ok {
		return value != nil
	}
	_, ok := readLeaf(source, path)
	return ok
}

// cutLast splits a dotted path at its last dot.
func cutLast(path string) (string, string, bool) {
	at := strings.LastIndex(path, ".")
	if at <= 0 {
		return "", "", false
	}
	return path[:at], path[at+1:], true
}

func truthOf(value bool) truth {
	if value {
		return truthTrue
	}
	return truthFalse
}

func isTruthy(value Node) bool {
	switch value := value.(type) {
	case bool:
		return value
	case string:
		return value != ""
	case nil:
		return false
	default:
		if number, ok := asNumber(value); ok {
			return number != 0
		}
		return true
	}
}
